// noc_router.v
// 5-port NoC router: N, S, E, W, L (local / tile-facing).
//
// DATAPATH
//   Storage-free crossbar. Flit storage lives in the link_buffer FIFOs on
//   every link (elastic-buffer flow control). One flit per output per cycle.
//
// ROUTING
//   Deterministic X-Y on ABSOLUTE destination coordinates: compare dst_x with
//   MY_X first, then dst_y with MY_Y. Flits are forwarded unmodified, so check
//   bits generated by the sending NI stay valid end to end.
//   X-Y forbids every Y-to-X turn, so the channel dependency graph is acyclic
//   and the mesh is deadlock-free without virtual channels.
//
// WORMHOLE OWNERSHIP (fixes the earlier interleaving bug)
//   Each input that has forwarded a HEAD holds a route (r_act/r_dst). An
//   output is LOCKED while any input holds a route to it, and only that owner
//   may use it until the owner's TAIL passes. Lock state is derived from the
//   per-input route registers, never stored twice, so the two cannot
//   disagree. The round-robin pointer only moves when a new HEAD is granted,
//   so arbitration memory is preserved for the whole packet.
//   Before this, the pointer advanced per flit and a second packet's HEAD
//   could win the output between the first packet's HEAD and TAIL.
//
// WHOLE-PACKET ADMISSION
//   A HEAD is granted only when the output has out_ready AND out_room (room
//   for a maximum-length packet downstream). See link_buffer.v for why this
//   makes a stalled locked output a definite fault rather than congestion.
//
// FAULT HANDLING (no rerouting: X-Y has one path, and detours would break the
// deadlock argument above; routing around faults is BIST's job)
//   Same-cycle checks on every input:
//     * check bits fail on an idle input        -> drop flit          (E_CHK)
//     * BODY/TAIL with no route held (orphan)    -> drop flit          (E_ORPHAN)
//     * HEAD to a missing/disabled/dead port     -> drop flit          (E_ROUTE)
//     * check bits fail mid-packet, or source
//       tag changes mid-packet                   -> replace the flit with a
//                                                   poison TAIL, release (E_CHK/E_PROTO)
//     * HEAD arrives mid-packet (lost TAIL)      -> send poison TAIL to close
//                                                   the old packet, keep the HEAD
//                                                   for the next cycle  (E_PROTO)
//   Flits that follow a dropped HEAD are orphans and drop the same way, so a
//   dropped packet drains out of the network on its own.
//   Per-output watchdog (shared prescaler, one small counter per output):
//     * LOCKED output, no progress for WD_LOCK_LIMIT ticks:
//         downstream ready  -> upstream lost the rest of the packet: emit a
//                              poison TAIL so downstream routes release
//         downstream stuck  -> mark the output dead
//       the owner input is released either way.
//     * UNLOCKED output with a waiting HEAD that cannot be admitted for
//       WD_STARVE_LIMIT ticks -> mark the output dead. Waiting HEADs are then
//       dropped as E_ROUTE and the requesting NI's timeout/retry takes over.
//   A poison TAIL carries the dropped packet's source and destination, data
//   NOC_POISON_DATA and the POISON bit. Downstream routers treat it as a TAIL
//   (releasing their routes); the destination NI discards the partial packet.
//
// DEBUG / BIST HOOKS
//   port_disable  forces an output unusable (availability decisions)
//   err_clear     clears all sticky flags, dead marks, counter and capture
//   in_err        sticky per-input error bits (layout in noc_defs.vh)
//   out_dead      outputs the watchdog has declared dead
//   out_wd        outputs whose watchdog has fired at least once
//   drop_cnt      saturating count of cycles with a drop/poison event
//   cap_*         first event since last clear: port and offending flit

`timescale 1ns/1ps
`include "noc_defs.vh"

module noc_router #(
    parameter integer MY_X            = 0,
    parameter integer MY_Y            = 0,
    // {L, W, E, S, N}: which ports have something real attached.
    parameter [4:0]   PORT_EXISTS     = 5'b11111,
    parameter integer WD_PRESCALE_W   = 2,    // one watchdog tick per 2**W cycles
    parameter integer WD_LOCK_LIMIT   = 8,    // ticks: locked output, no progress
    parameter integer WD_STARVE_LIMIT = 64,   // ticks: waiting HEAD, never admitted
    parameter integer WD_CNT_W        = 7
) (
    input  wire                     clk,
    input  wire                     rst_n,

    // Port order for every 5-wide bus: 0=N, 1=S, 2=E, 3=W, 4=L
    input  wire [4:0]               in_valid,
    output wire [4:0]               in_ready,
    input  wire [5*`NOC_FLIT_W-1:0] in_flit,

    output wire [4:0]               out_valid,
    input  wire [4:0]               out_ready,
    input  wire [4:0]               out_room,
    output wire [5*`NOC_FLIT_W-1:0] out_flit,

    input  wire [4:0]               port_disable,
    input  wire                     err_clear,
    output wire [5*`NOC_E_W-1:0]    in_err,
    output wire [4:0]               out_dead,
    output wire [4:0]               out_wd,
    output wire [7:0]               drop_cnt,
    output wire                     cap_valid,
    output wire [2:0]               cap_port,
    output wire [`NOC_FLIT_W-1:0]   cap_flit
);

`include "noc_funcs.vh"

    localparam FW = `NOC_FLIT_W;
    localparam XW = `NOC_X_W;
    localparam YW = `NOC_Y_W;
    localparam IW = `NOC_ID_W;
    localparam N = `NOC_P_N, S = `NOC_P_S, E = `NOC_P_E, W = `NOC_P_W, L = `NOC_P_L;
    localparam [1:0] T_BODY = `NOC_T_BODY, T_HEAD = `NOC_T_HEAD,
                     T_HEADTAIL = `NOC_T_HEADTAIL, T_TAIL = `NOC_T_TAIL;
    localparam [WD_CNT_W-1:0] WD_MAX = {WD_CNT_W{1'b1}};

    generate
        if (WD_PRESCALE_W < 1) begin : rt_check_presc
            NOC_CONFIG_ERROR_router_wd_prescale_must_be_at_least_1 u_err ();
        end
        if ((WD_LOCK_LIMIT > (1 << WD_CNT_W) - 1) || (WD_STARVE_LIMIT > (1 << WD_CNT_W) - 1)) begin : rt_check_wd
            NOC_CONFIG_ERROR_router_wd_limit_exceeds_counter u_err ();
        end
        if ((MY_X >= `NOC_MESH_X) || (MY_Y >= `NOC_MESH_Y)) begin : rt_check_coord
            NOC_CONFIG_ERROR_router_coordinates_outside_mesh u_err ();
        end
    endgenerate

    // X-Y routing on absolute coordinates.
    function [2:0] route_of;
        input [XW-1:0] dx;
        input [YW-1:0] dy;
        begin
            if (dx < MY_X)       route_of = W;
            else if (dx > MY_X)  route_of = E;
            else if (dy < MY_Y)  route_of = N;
            else if (dy > MY_Y)  route_of = S;
            else                 route_of = L;
        end
    endfunction

    // ---------------------------------------------------------------
    // Unpack
    // ---------------------------------------------------------------
    wire [FW-1:0] fin [0:4];
    genvar g;
    generate
        for (g = 0; g < 5; g = g + 1) begin : unpack
            assign fin[g] = in_flit[g*FW +: FW];
        end
    endgenerate

    // ---------------------------------------------------------------
    // State
    // ---------------------------------------------------------------
    reg          r_act [0:4];     // input holds a route (mid-packet)
    reg [2:0]    r_dst [0:4];     // output that route uses
    reg [IW-1:0] r_src [0:4];     // source tag of the packet holding it
    reg [XW-1:0] r_dx  [0:4];     // destination of that packet, for poison TAILs
    reg [YW-1:0] r_dy  [0:4];
    reg [2:0]    rr_ptr [0:4];    // per-output round-robin start, 0..4
    reg [4:0]    dead;
    reg [WD_CNT_W-1:0] wd_cnt [0:4];
    reg [WD_PRESCALE_W-1:0] presc;
    wire         tick = &presc;

    wire [4:0] out_ok = PORT_EXISTS & ~port_disable & ~dead;

    // ---------------------------------------------------------------
    // Per-input classification (combinational)
    // ---------------------------------------------------------------
    reg [1:0]    f_type  [0:4];
    reg          f_pois  [0:4];
    reg [IW-1:0] f_src   [0:4];
    reg [XW-1:0] f_dx    [0:4];
    reg [YW-1:0] f_dy    [0:4];
    reg          f_ok    [0:4];
    reg [2:0]    f_route [0:4];

    reg a_drop  [0:4];   // idle input: consume and discard
    reg a_req   [0:4];   // idle input: legal HEAD requesting f_route
    reg a_fwd   [0:4];   // routed input: good BODY/TAIL to forward
    reg a_bad   [0:4];   // routed input: bad flit, replace with poison TAIL
    reg a_proto [0:4];   // routed input: HEAD mid-packet, close old packet

    reg e_chk [0:4], e_orph [0:4], e_route [0:4], e_proto [0:4];

    integer ci;
    always @(*) begin
        for (ci = 0; ci < 5; ci = ci + 1) begin
            f_type[ci]  = fin[ci][`NOC_F_TYPE_LSB +: 2];
            f_pois[ci]  = fin[ci][`NOC_F_POISON];
            f_src[ci]   = fin[ci][`NOC_F_SRC_LSB  +: IW];
            f_dx[ci]    = fin[ci][`NOC_F_DSTX_LSB +: XW];
            f_dy[ci]    = fin[ci][`NOC_F_DSTY_LSB +: YW];
            f_ok[ci]    = noc_chk_ok(fin[ci]);
            f_route[ci] = route_of(f_dx[ci], f_dy[ci]);

            a_drop[ci] = 1'b0; a_req[ci] = 1'b0; a_fwd[ci] = 1'b0;
            a_bad[ci]  = 1'b0; a_proto[ci] = 1'b0;
            e_chk[ci]  = 1'b0; e_orph[ci] = 1'b0; e_route[ci] = 1'b0; e_proto[ci] = 1'b0;

            if (in_valid[ci] && PORT_EXISTS[ci]) begin
                if (!r_act[ci]) begin
                    if (!f_ok[ci]) begin
                        a_drop[ci] = 1'b1; e_chk[ci] = 1'b1;
                    end else if (f_type[ci] == T_BODY || f_type[ci] == T_TAIL) begin
                        a_drop[ci] = 1'b1; e_orph[ci] = 1'b1;
                    end else if (f_pois[ci] || !out_ok[f_route[ci]] || f_route[ci] == ci) begin
                        // no U-turns: X-Y never sends a flit back where it came from
                        a_drop[ci] = 1'b1; e_route[ci] = 1'b1;
                    end else begin
                        a_req[ci] = 1'b1;
                    end
                end else begin
                    if (!f_ok[ci]) begin
                        a_bad[ci] = 1'b1; e_chk[ci] = 1'b1;
                    end else if (f_type[ci] == T_HEAD || f_type[ci] == T_HEADTAIL) begin
                        a_proto[ci] = 1'b1; e_proto[ci] = 1'b1;
                    end else if (f_src[ci] != r_src[ci] || (f_pois[ci] && f_type[ci] != T_TAIL)) begin
                        a_bad[ci] = 1'b1; e_proto[ci] = 1'b1;
                    end else begin
                        a_fwd[ci] = 1'b1;   // includes an upstream poison TAIL
                    end
                end
            end
        end
    end

    // ---------------------------------------------------------------
    // Per-output: ownership, arbitration, watchdog actions, crossbar
    // ---------------------------------------------------------------
    reg          o_lock  [0:4];
    reg [2:0]    o_own   [0:4];
    reg          o_req   [0:4];
    reg          o_grant [0:4];
    reg [2:0]    o_win   [0:4];
    reg          o_valid [0:4];
    reg [FW-1:0] o_flit  [0:4];
    reg          o_wdf   [0:4];   // watchdog fired on this output this cycle
    reg          o_kill  [0:4];   // mark this output dead this cycle

    reg          c_in    [0:4];   // consume input flit (drives in_ready)
    reg          rel_in  [0:4];   // release input's route
    reg          set_in  [0:4];   // input's HEAD granted: take a route
    reg [2:0]    set_dst [0:4];

    reg          ev_any;
    reg [2:0]    ev_port;
    reg [FW-1:0] ev_flit;

    integer oo, ii, kk, cand;
    reg     found, mv;
    reg [2:0] own, win;

    always @(*) begin
        // defaults for loop temporaries, so no path leaves them unassigned
        // (otherwise synthesis infers latches)
        found = 1'b0; mv = 1'b0; own = 3'd0; win = 3'd0; cand = 0; kk = 0;

        for (ii = 0; ii < 5; ii = ii + 1) begin
            c_in[ii]    = a_drop[ii];
            rel_in[ii]  = 1'b0;
            set_in[ii]  = 1'b0;
            set_dst[ii] = 3'd0;
        end

        for (oo = 0; oo < 5; oo = oo + 1) begin
            o_lock[oo] = 1'b0; o_own[oo] = 3'd0; o_req[oo] = 1'b0;
            o_grant[oo] = 1'b0; o_win[oo] = 3'd0;
            o_valid[oo] = 1'b0; o_flit[oo] = {FW{1'b0}};
            o_wdf[oo] = 1'b0; o_kill[oo] = 1'b0;

            for (ii = 0; ii < 5; ii = ii + 1) begin
                if (r_act[ii] && r_dst[ii] == oo) begin
                    o_lock[oo] = 1'b1;
                    o_own[oo]  = ii;
                end
                if (a_req[ii] && f_route[ii] == oo)
                    o_req[oo] = 1'b1;
            end

            if (o_lock[oo]) begin
                own = o_own[oo];
                mv  = (a_fwd[own] || a_bad[own] || a_proto[own]) && out_ready[oo];
                if (mv) begin
                    o_valid[oo] = 1'b1;
                    if (a_fwd[own]) begin
                        o_flit[oo] = fin[own];
                        c_in[own]  = 1'b1;
                        if (f_type[own] == T_TAIL)
                            rel_in[own] = 1'b1;
                    end else begin
                        o_flit[oo]  = noc_make_flit(T_TAIL, 1'b1, r_src[own], r_dx[own], r_dy[own],
                                                    `NOC_POISON_DATA);
                        c_in[own]   = a_bad[own];   // a_proto keeps its HEAD for next cycle
                        rel_in[own] = 1'b1;
                    end
                end else if (wd_cnt[oo] >= WD_LOCK_LIMIT) begin
                    o_wdf[oo]   = 1'b1;
                    rel_in[own] = 1'b1;
                    if (out_ready[oo]) begin
                        o_valid[oo] = 1'b1;
                        o_flit[oo]  = noc_make_flit(T_TAIL, 1'b1, r_src[own], r_dx[own], r_dy[own],
                                                    `NOC_POISON_DATA);
                    end else begin
                        o_kill[oo] = 1'b1;
                    end
                end
            end else begin
                found = 1'b0;
                win   = 3'd0;
                for (kk = 0; kk < 5; kk = kk + 1) begin
                    cand = rr_ptr[oo] + kk;
                    if (cand >= 5) cand = cand - 5;
                    if (!found && a_req[cand] && f_route[cand] == oo) begin
                        found = 1'b1;
                        win   = cand;
                    end
                end
                if (found && out_ready[oo] && out_room[oo]) begin
                    o_grant[oo] = 1'b1;
                    o_win[oo]   = win;
                    o_valid[oo] = 1'b1;
                    o_flit[oo]  = fin[win];
                    c_in[win]   = 1'b1;
                    if (f_type[win] == T_HEAD) begin
                        set_in[win]  = 1'b1;
                        set_dst[win] = oo;
                    end
                end else if (o_req[oo] && wd_cnt[oo] >= WD_STARVE_LIMIT) begin
                    o_wdf[oo]  = 1'b1;
                    o_kill[oo] = 1'b1;
                end
            end
        end

        // first event this cycle, for the capture register
        ev_any  = 1'b0;
        ev_port = 3'd0;
        ev_flit = {FW{1'b0}};
        for (ii = 4; ii >= 0; ii = ii - 1) begin
            if ((a_drop[ii] || ((a_bad[ii] || a_proto[ii]) && rel_in[ii]))) begin
                ev_any  = 1'b1;
                ev_port = ii;
                ev_flit = fin[ii];
            end
        end
        for (oo = 4; oo >= 0; oo = oo - 1) begin
            if (o_wdf[oo] && !ev_any) begin
                ev_any  = 1'b1;
                ev_port = oo;
                ev_flit = noc_make_flit(T_TAIL, 1'b1, r_src[o_own[oo]], r_dx[o_own[oo]],
                                        r_dy[o_own[oo]], `NOC_POISON_DATA);
            end
        end
    end

    // ---------------------------------------------------------------
    // Outputs
    // ---------------------------------------------------------------
    generate
        for (g = 0; g < 5; g = g + 1) begin : pack
            assign out_valid[g]          = o_valid[g];
            assign out_flit[g*FW +: FW]  = o_flit[g];
            assign in_ready[g]           = c_in[g];
        end
    endgenerate

    reg [5*`NOC_E_W-1:0] err_q;
    reg [4:0]            wd_q;
    reg [7:0]            drop_q;
    reg                  cap_v_q;
    reg [2:0]            cap_p_q;
    reg [FW-1:0]         cap_f_q;

    assign in_err    = err_q;
    assign out_dead  = dead;
    assign out_wd    = wd_q;
    assign drop_cnt  = drop_q;
    assign cap_valid = cap_v_q;
    assign cap_port  = cap_p_q;
    assign cap_flit  = cap_f_q;

    // ---------------------------------------------------------------
    // Sequential
    // ---------------------------------------------------------------
    integer si;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (si = 0; si < 5; si = si + 1) begin
                r_act[si]  <= 1'b0;
                r_dst[si]  <= 3'd0;
                r_src[si]  <= {IW{1'b0}};
                r_dx[si]   <= {XW{1'b0}};
                r_dy[si]   <= {YW{1'b0}};
                rr_ptr[si] <= 3'd0;
                wd_cnt[si] <= {WD_CNT_W{1'b0}};
            end
            dead    <= 5'b0;
            presc   <= {WD_PRESCALE_W{1'b0}};
            err_q   <= {5*`NOC_E_W{1'b0}};
            wd_q    <= 5'b0;
            drop_q  <= 8'd0;
            cap_v_q <= 1'b0;
            cap_p_q <= 3'd0;
            cap_f_q <= {FW{1'b0}};
        end else begin
            presc <= presc + 1'b1;

            for (si = 0; si < 5; si = si + 1) begin
                // route state per input
                if (set_in[si]) begin
                    r_act[si] <= 1'b1;
                    r_dst[si] <= set_dst[si];
                    r_src[si] <= f_src[si];
                    r_dx[si]  <= f_dx[si];
                    r_dy[si]  <= f_dy[si];
                end else if (rel_in[si]) begin
                    r_act[si] <= 1'b0;
                end

                // round-robin pointer moves only when a new packet is granted
                if (o_grant[si])
                    rr_ptr[si] <= (o_win[si] == 3'd4) ? 3'd0 : o_win[si] + 3'd1;

                // watchdog: count ticks while the output has work but makes no progress
                if (!(o_lock[si] || o_req[si]) || (o_valid[si] && out_ready[si]) || o_wdf[si])
                    wd_cnt[si] <= {WD_CNT_W{1'b0}};
                else if (tick && wd_cnt[si] != WD_MAX)
                    wd_cnt[si] <= wd_cnt[si] + 1'b1;
            end

            if (err_clear) begin
                dead    <= 5'b0;
                err_q   <= {5*`NOC_E_W{1'b0}};
                wd_q    <= 5'b0;
                drop_q  <= 8'd0;
                cap_v_q <= 1'b0;
            end else begin
                for (si = 0; si < 5; si = si + 1) begin
                    if (o_kill[si]) dead[si] <= 1'b1;
                    if (o_wdf[si])  wd_q[si] <= 1'b1;
                    if (e_chk[si] && c_in[si])                      err_q[si*`NOC_E_W + `NOC_E_CHK]    <= 1'b1;
                    if (e_orph[si])                                 err_q[si*`NOC_E_W + `NOC_E_ORPHAN] <= 1'b1;
                    if (e_route[si])                                err_q[si*`NOC_E_W + `NOC_E_ROUTE]  <= 1'b1;
                    if (e_proto[si] && rel_in[si])                  err_q[si*`NOC_E_W + `NOC_E_PROTO]  <= 1'b1;
                end
                if (ev_any && drop_q != 8'hFF)
                    drop_q <= drop_q + 1'b1;
                if (ev_any && !cap_v_q) begin
                    cap_v_q <= 1'b1;
                    cap_p_q <= ev_port;
                    cap_f_q <= ev_flit;
                end
            end
        end
    end

endmodule
